// Function safeFetch(url)
// Check response.ok, throw if false, return parsed JSON

// Use safeFetch to get todo 1, log title
// .catch() for errors

questions.solution:
function safeFetch(url) {
  return fetch(url)
    .then(response => {
      if (!response.ok) {
        throw new Error('Request failed: ' + response.status);
      }
      return response.json();
    });
}

safeFetch('https://jsonplaceholder.typicode.com/todos/1')
  .then(todo => console.log(todo.title))
  .catch(error => console.log(error.message));

