const students = [
  { name: 'Amara', score: 88 },
  { name: 'Bayo', score: 45 },
  { name: 'Chidi', score: 72 }
];

// Stringify into 'stored' variable
// Parse back
// Filter score >= 60
// Log each passing name

questions.solution:
const students = [
  { name: 'Amara', score: 88 },
  { name: 'Bayo', score: 45 },
  { name: 'Chidi', score: 72 }
];

const stored = JSON.stringify(students);
const parsed = JSON.parse(stored);

const passing = parsed.filter(s => s.score >= 60);
passing.forEach(s => console.log(s.name));

questions.starter:
// Fetch 10 todos
// Filter: completed === true
// Log: count of completed, first completed title

questions.solution:
fetch('https://jsonplaceholder.typicode.com/todos?_limit=10')
  .then(response => {
    if (!response.ok) throw new Error('HTTP error: ' + response.status);
    return response.json();
  })
  .then(todos => {
    const completed = todos.filter(t => t.completed === true);
    console.log(completed.length);
    if (completed.length > 0) {
      console.log(completed[0].title);
    }
  })
  .catch(error => console.log(error.message));
